    gFmsEngineHours += 1.0 / 36000.0;

    gFmsCoolantTemperatureC = fmsWaveValue(tick + 40, 260, 78, 94);
    gFmsEngineOilTemperatureC = (double)fmsWaveValue(tick + 80, 320, 82, 104);
    gFmsAmbientAirTemperatureC = (double)fmsWaveValue(tick, 600, 12, 28);
    gFmsServiceBrakeAirPressure1Kpa = (unsigned int)fmsWaveValue(tick, 220, 700, 900);
    gFmsServiceBrakeAirPressure2Kpa = (unsigned int)fmsWaveValue(tick + 25, 220, 700, 900);
    gFmsTirePressureKpa[0] = 900 + (unsigned int)fmsWaveValue(tick + 0, 700, 0, 20);
    gFmsTirePressureKpa[1] = 890 + (unsigned int)fmsWaveValue(tick + 70, 700, 0, 20);
    gFmsTirePressureKpa[2] = 900 + (unsigned int)fmsWaveValue(tick + 140, 700, 0, 20);
    gFmsTirePressureKpa[3] = 890 + (unsigned int)fmsWaveValue(tick + 210, 700, 0, 20);
    gFmsTirePressureKpa[4] = 900 + (unsigned int)fmsWaveValue(tick + 280, 700, 0, 20);
    gFmsTirePressureKpa[5] = 890 + (unsigned int)fmsWaveValue(tick + 350, 700, 0, 20);
    gFmsTireTemperatureC[0] = 15.125 + (double)fmsWaveValue(tick + 0, 500, 0, 5);
    gFmsTireTemperatureC[1] = 15.125 + (double)fmsWaveValue(tick + 60, 500, 0, 5);
    gFmsTireTemperatureC[2] = 15.125 + (double)fmsWaveValue(tick + 120, 500, 0, 5);
    gFmsTireTemperatureC[3] = 15.125 + (double)fmsWaveValue(tick + 180, 500, 0, 5);
    gFmsTireTemperatureC[4] = 15.125 + (double)fmsWaveValue(tick + 240, 500, 0, 5);
    gFmsTireTemperatureC[5] = 15.125 + (double)fmsWaveValue(tick + 300, 500, 0, 5);

    gFmsAtLeastOnePtoEngaged = ((tick % 500) > 420) ? 1 : 0;
    gFmsPtoState = gFmsAtLeastOnePtoEngaged ? 5 : 31;
    gFmsFrontDoorOpen = (gFmsWheelBasedSpeedKph < 0.5 && ((tick / 20) % 2)) ? 1 : 0;
    gFmsMiddleDoorOpen = gFmsFrontDoorOpen;
    gFmsRearDoorOpen = 0;
    gFmsAlternatorSpeedRpm = gFmsEngineSpeedRpm * 2.0;
