    gFmsTellTaleStatus[1][6] = gFmsBrakeSwitch ? 3 : 0;
    gFmsTellTaleStatus[1][7] = gFmsBrakeSwitch ? 3 : 0;
    gFmsTellTaleStatus[1][11] = (gFmsCoolantTemperatureC > 88) ? 2 : 0;
    gFmsTellTaleStatus[1][12] = (gFmsEngineSpeedRpm < 750.0) ? 2 : 0;
    gFmsTellTaleStatus[1][13] = (gFmsCoolantTemperatureC > 92) ? 3 : 0;
    gFmsTellTaleStatus[2][0] = gFmsBrakeSwitch ? 2 : 0;
    gFmsTellTaleStatus[2][3] = ((tick % 500) > 420) ? 3 : 0;
    gFmsTellTaleStatus[2][4] = ((tick % 500) > 420) ? 3 : 0;
    gFmsTellTaleStatus[2][10] = (gFmsDieselExhaustFluidLevelPercent < 62) ? 2 : 0;
    gFmsTellTaleStatus[3][1] = ((tick % 300) > 260) ? 3 : 0;
    gFmsTellTaleStatus[3][2] = ((tick % 400) > 350) ? 3 : 0;
    gFmsTellTaleStatus[3][3] = ((tick % 600) > 520) ? 2 : 0;
    gFmsTellTaleStatus[3][7] = gFmsCruiseControlActive ? 3 : 0;
    gFmsTellTaleStatus[3][8] = gFmsAtLeastOnePtoEngaged ? 3 : 0;
    gFmsTellTaleStatus[3][12] = gFmsVehicleOverspeed ? 2 : 0;

    fmsUpdateClockLocked();

    LeaveCriticalSection(&gFmsParamLock);
